import {initPixelMay} from './may-pixel.js';
const $=s=>document.querySelector(s),screen=$('#demo-screen');
const assets={AAPLx:{name:'Apple token',price:243.42,icon:'A'},NVDAx:{name:'NVIDIA token',price:162.15,icon:'N'}};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
let cash=75000,holdings={AAPLx:.5,NVDAx:.6},symbol='AAPLx',side='buy',stage='home',amount='50',receipt=null,may;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;
function syncMotion(){document.body.classList.toggle('motion-off',!motion);$('#motion').textContent=`Motion ${motion?'on':'off'}`;$('#motion').setAttribute('aria-pressed',String(!motion));}syncMotion();
$('#motion').onclick=()=>{motion=!motion;syncMotion();};reduced.addEventListener('change',e=>{motion=!e.matches;syncMotion();});
function react(mood,message){$('#may-message').textContent=message;may?.react(mood,message,6000);}
initPixelMay({host:$('#mascot'),getMotion:()=>motion,getChapter:()=>stage==='review'?'research':'work',say:t=>$('#may-message').textContent=t}).then(m=>{may=m;let raf;const tick=()=>{if(!document.hidden)m.update();raf=requestAnimationFrame(tick);};tick();window.addEventListener('pagehide',()=>cancelAnimationFrame(raf),{once:true});}).catch(()=>{$('#mascot').textContent='☁ Mây';});
const maxCents=()=>side==='buy'?cash:Math.floor(holdings[symbol]*assets[symbol].price*100+1e-7);
function quote(){const valid=/^\d+(?:[.,]\d{1,2})?$/.test(amount),cents=valid?Math.round(Number(amount.replace(',','.'))*100):0;const fee=Math.round(cents*.0025);return {cents,fee,quantity:(side==='buy'?cents-fee:cents)/100/assets[symbol].price,error:!valid||cents<=0?'Enter an amount greater than $0, with up to two decimals.':cents>maxCents()?`Available to ${side}: ${money(maxCents()/100)}.`:cents<=fee?'Amount is too small.':''};}
function lines(items){return `<dl class="receipt-lines">${items.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function go(next){stage=next;render();screen.focus({preventScroll:true});const messages={home:['coding','Choose a token to explore. Everything here is sample data.'],amount:['coding','Try an amount. I’ll help you check the sample balance.'],review:['thinking','Check the quantity and sample fee before confirming.'],success:['happy','Done! Only the sample ledger changed.']};react(...messages[next]);}
function render(){document.querySelectorAll('[data-stage]').forEach(el=>{if(el.dataset.stage===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});const a=assets[symbol];
if(stage==='home'){screen.innerHTML=`<p class="demo-caption">YOUR PRACTICE WALLET</p><div class="wallet-card"><p>Available sample dollars</p><h3>${money(cash/100)}</h3><small>USDC-inspired balance · fixed USD fixtures</small></div><h3>Your sample assets</h3>${Object.entries(assets).map(([key,v])=>`<button class="asset-row" data-action="asset" data-symbol="${key}" aria-label="Explore ${key}"><span class="asset-icon">${v.icon}</span><span><strong>${key}</strong><small>${v.name}</small></span><span class="asset-price"><strong>${money(v.price)}</strong><small>${holdings[key].toFixed(6)} held →</small></span></button>`).join('')}<p class="demo-caption">Fixed sample prices. Tokenized stock exposure is not direct ownership of company shares. Select an asset to try buying or selling.</p>`;}
if(stage==='amount'){screen.innerHTML=`<button class="back" data-action="home">← Wallet</button><h3 class="trade-title">${symbol} <span class="demo-caption">${a.name}</span></h3><p class="demo-caption">Fixed sample price ${money(a.price)}</p><div class="segmented" aria-label="Trade direction"><button data-action="buy" aria-pressed="${side==='buy'}">Buy</button><button data-action="sell" aria-pressed="${side==='sell'}">Sell</button></div><label class="amount-label" for="trade-amount">Amount in sample USD</label><input class="amount-input" id="trade-amount" inputmode="decimal" autocomplete="off" aria-describedby="amount-error available" value="${amount}"><p class="demo-caption" id="available">Available: ${money(maxCents()/100)}</p><div class="presets">${(side==='buy'?['10','50','100','Max']:['25%','50%','100%']).map(v=>`<button data-action="preset" data-value="${v}">${v}</button>`).join('')}</div><p class="error" id="amount-error" aria-live="polite"></p><p class="demo-caption">Illustrative fee: 0.25%, rounded to cents. This is a walkthrough assumption, not N.E.D’s published pricing.</p><button class="button purple-button wide" data-action="review" id="review-button">Review sample ${side} →</button>`;validate();}
if(stage==='review'){const q=quote();screen.innerHTML=`<button class="back" data-action="amount">← Edit amount</button><h3 class="trade-title">Review sample ${side}</h3>${lines([['Asset',symbol],['Sample amount',money(q.cents/100)],['Illustrative fee',money(q.fee/100)],[side==='buy'?'Tokens received':'Tokens sold',q.quantity.toFixed(6)],[side==='buy'?'Total debit':'Net credit',money((side==='buy'?q.cents:q.cents-q.fee)/100)]])}<label class="ack"><input type="checkbox" id="ack">I understand this changes sample data only. No real funds, shares or tokens are transferred.</label><button class="button purple-button wide" data-action="confirm" id="confirm-trade" disabled>Confirm sample ${side}</button>`;}
if(stage==='success'){screen.innerHTML=`<div class="success"><img src="assets/ned/teddy-happy.png" alt="Teddy, N.E.D’s purple bear mascot, celebrates"><p class="demo-caption">SAMPLE TRANSACTION COMPLETE</p><h3>${receipt.side==='buy'?'Added to':'Sold from'} your<br>practice wallet.</h3><p>${receipt.quantity.toFixed(6)} ${receipt.symbol} · ${money(receipt.cents/100)}</p></div>${lines([['Sample dollars remaining',money(cash/100)],['Sample holding',`${holdings[symbol].toFixed(6)} ${symbol}`]])}<button class="button purple-button wide" data-action="home">Back to wallet →</button><button class="button wide" data-action="try-sell">Try a sample sell</button>`;}}
function validate(){const q=quote();$('#amount-error').textContent=q.error;$('#trade-amount').setAttribute('aria-invalid',String(!!q.error));$('#review-button').disabled=!!q.error;}
screen.addEventListener('input',e=>{if(e.target.id==='trade-amount'){amount=e.target.value;validate();}if(e.target.id==='ack')$('#confirm-trade').disabled=!e.target.checked;});
screen.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
if(action==='asset'){symbol=b.dataset.symbol;side='buy';amount='50';go('amount');}
else if(['home','amount'].includes(action))go(action);
else if(action==='buy'||action==='sell'){side=action;amount='50';go('amount');}
else if(action==='preset'){const v=b.dataset.value;amount=v==='Max'?(maxCents()/100).toFixed(2):v.endsWith('%')?(Math.floor(maxCents()*parseInt(v)/100)/100).toFixed(2):v;render();$('#trade-amount').focus();}
else if(action==='review'&&!quote().error)go('review');
else if(action==='confirm'&&stage==='review'&&$('#ack').checked){const q=quote();if(q.error)return;receipt={...q,side,symbol};if(side==='buy'){cash-=q.cents;holdings[symbol]+=q.quantity;}else{cash+=q.cents-q.fee;holdings[symbol]=Math.max(0,holdings[symbol]-q.quantity);}go('success');}
else if(action==='try-sell'){side='sell';amount=(Math.floor(maxCents()/2)/100).toFixed(2);go('amount');}});
$('#reset-demo').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{cash=75000;holdings={AAPLx:.5,NVDAx:.6};symbol='AAPLx';side='buy';amount='50';receipt=null;$('#reset-dialog').close();go('home');};render();
